import test from 'node:test';
import assert from 'node:assert/strict';
import {selectRecords} from '../src/select.js';
const make=()=>[{id:'a',tenantId:'t1'},{id:'b',tenantId:'t2'},{id:'A',tenantId:'t1'},{id:'c',tenantId:'t1'}];
test('same tenant selected',()=>assert.deepEqual(selectRecords(make(),'t1',['a','b']).map(x=>x.id),['a']));
test('empty means empty',()=>assert.deepEqual(selectRecords(make(),'t1',[]),[]));
test('case identity',()=>assert.deepEqual(selectRecords(make(),'t1',['A']).map(x=>x.id),['A']));
test('source order',()=>assert.deepEqual(selectRecords(make(),'t1',['c','a']).map(x=>x.id),['a','c']));
test('input preserved',()=>{const rows=make();const before=structuredClone(rows);selectRecords(rows,'t1',['a']);assert.deepEqual(rows,before);});
